import{_ as i,a0 as r,w as l,s as p,I as o,x as a,a1 as t,A as e,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"cron 与 anacron：如何在 Linux 中计划任务 | LCTT x X-CMD","titleTemplate":false,"description":"cron 与 anacron：如何在 Linux 中计划任务 | LCTT (201706) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"cron 与 anacron：如何在 Linux 中计划任务 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"cron 与 anacron：如何在 Linux 中计划任务 | LCTT (201706) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201706/20170601 Cron Vs Anacron How to Schedule Jobs Using Anacron on Linux","title":"cron 与 anacron：如何在 Linux 中计划任务","tag":"201706","desc":""},"relativePath":"201706/20170601 Cron Vs Anacron How to Schedule Jobs Using Anacron on Linux.md","filePath":"[post].md"}'),c={name:"201706/20170601 Cron Vs Anacron How to Schedule Jobs Using Anacron on Linux.md"};function u(b,n,h,k,g,m){const s=r("Link");return l(),p("div",null,[n[22]||(n[22]=o("h1",{id:"cron-与-anacron-如何在-linux-中计划任务",tabindex:"-1"},[a("cron 与 anacron：如何在 Linux 中计划任务 "),o("a",{class:"header-anchor",href:"#cron-与-anacron-如何在-linux-中计划任务","aria-label":"Permalink to “cron 与 anacron：如何在 Linux 中计划任务”"},"​")],-1)),n[23]||(n[23]=o("p",null,"在本篇中，我们会解释 cron 和 anacron，并向你展示如何在 Linux 中设置 anacron。我们也会比较这两个工具。",-1)),o("p",null,[n[1]||(n[1]=a("要",-1)),t(s,{href:"https://www.tecmint.com/linux-cron-alternative-at-command-to-schedule-tasks/"},{default:e(()=>[...n[0]||(n[0]=[a("在一个给定时间或者稍后安排一个任务",-1)])]),_:1}),n[2]||(n[2]=a("，你可以使用 ",-1)),n[3]||(n[3]=o("code",null,"at",-1)),n[4]||(n[4]=a(" 或者 ",-1)),n[5]||(n[5]=o("code",null,"batch",-1)),n[6]||(n[6]=a(" 命令，要使命令能够重复运行，你可以使用 cron 以及 anacron 工具。",-1))]),o("p",null,[t(s,{href:"https://www.tecmint.com/11-cron-scheduling-task-examples-in-linux/"},{default:e(()=>[...n[7]||(n[7]=[a("cron",-1)])]),_:1}),n[8]||(n[8]=a(" - 是一个用于运行计划任务如系统备份、更新等的守护进程。它适合在那些 24X7 不间断运行的机器如服务器上运行的计划任务。",-1))]),n[24]||(n[24]=d(`<p>命令/脚本被写在 cron 任务脚本中，它是在 <code>crontab</code> 文件中被安排的。系统默认的 <code>crontab</code> 文件是 <code>/etc/crontab</code>，但是每个用户也可以创建自己的 <code>crontab</code> 文件来在特定时间运行用户定义的命令。</p><p>要创建一份个人 <code>crontab</code> 文件，只要输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ crontab -e</span></span></code></pre></div><h3 id="如何在-linux-中设置-anacron" tabindex="-1">如何在 Linux 中设置 anacron <a class="header-anchor" href="#如何在-linux-中设置-anacron" aria-label="Permalink to “如何在 Linux 中设置 anacron”">​</a></h3><p>anacron 用于以天为单位的频率运行命令。它的工作与 cron 稍有不同，<strong>它假设机器不会一直开机</strong>。</p><p>cron 也适合在那些不会 24X7 运行如笔记本以及桌面电脑的机器上运行每日、每周以及每月的计划任务（LCTT 译注：不适合按小时、分钟执行任务）。</p><p>假设你有一个计划任务（比如备份脚本）要使用 cron 在每天半夜运行，也许你以及睡着，那时你的桌面/笔记本电脑已经关机。你的备份脚本就不会被运行。</p><p>然而，如果你使用 anacron，你可以确保在你下次开启桌面/笔记本电脑的时候，备份脚本会被执行。</p><h3 id="anacron-如何在-linux-工作" tabindex="-1">anacron 如何在 Linux 工作 <a class="header-anchor" href="#anacron-如何在-linux-工作" aria-label="Permalink to “anacron 如何在 Linux 工作”">​</a></h3><p>anacron 任务被列在 <code>/etc/anacrontab</code> 中，任务可以使用下面的格式（anacron 文件中的注释必须以 <code>#</code> 号开始）安排。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>period   delay   job-identifier   command</span></span></code></pre></div><p>从上面的格式中：</p><ul><li><code>period</code> - 这是任务的频率，以天来指定，或者是 <code>@daily</code>、<code>@weekly</code>、<code>@monthly</code> 代表每天、每周、每月一次。你也可以使用数字：<code>1</code> - 每天、<code>7</code> - 每周、<code>30</code> - 每月，或者 <code>N</code> - 几天。</li><li><code>delay</code> - 这是在执行一个任务前等待的分钟数。</li><li><code>job-id</code> - 这是写在日志文件中任务的独特名字。</li><li><code>command</code> - 这是要执行的命令或 shell 脚本。</li></ul><p>要浏览示例文件，输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /var/spool/anacron/</span></span>
<span class="line"><span>total 12</span></span>
<span class="line"><span>-rw------- 1 root root 9 Jun  1 10:25 cron.daily</span></span>
<span class="line"><span>-rw------- 1 root root 9 May 27 11:01 cron.monthly</span></span>
<span class="line"><span>-rw------- 1 root root 9 May 30 10:28 cron.weekly</span></span></code></pre></div><p>这是实际发生的：</p><ul><li>anacron 会检查任务是否已经在 <code>period</code> 字段指定的时间被被执行了。如果没有，则在等待 <code>delay</code> 字段中指定的分钟数后，执行 <code>command</code> 字段中指定的命令。</li><li>一旦任务被执行了，它会使用 <code>job-id</code>（时间戳文件名）字段中指定的名称将日期记录在 <code>/var/spool/anacron</code> 目录中的时间戳文件中。</li></ul><p>现在让我们看一个例子。这个会每天运行 <code>/home/aaronkilik/bin/backup.sh</code> 脚本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@daily    10    example.daily   /bin/bash /home/aaronkilik/bin/backup.sh</span></span></code></pre></div><p>当机器在 <code>backup.sh</code> 期望被运行时是关机的，anacron 会在机器开机十分钟之后运行它，而不用再等待 7 天。</p><p>这里有两个你应该理解的 anacrontab 文件的重要变量：</p><ul><li><p><code>START_HOURS_RANGE</code> - 这个设置任务开始运行的时间范围（也就是任务只在这几个小时内运行）。</p></li><li><p><code>RANDOM_DELAY</code> - 这定义添加到用户定义的任务延迟的最大随机延迟（默认为 45）。</p></li></ul><p>这是你的 anacrontab 文件可能看上去的样子。</p><p>Anacron – <code>/etc/anacrontab</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># /etc/anacrontab: configuration file for anacron</span></span>
<span class="line"><span># See anacron(8) and anacrontab(5) for details.</span></span>
<span class="line"><span>SHELL=/bin/sh</span></span>
<span class="line"><span>PATH=/usr/local/sbin:/usr/local/bin:/sbin:/bin:/usr/sbin:/usr/bin</span></span>
<span class="line"><span>HOME=/root</span></span>
<span class="line"><span>LOGNAME=root</span></span>
<span class="line"><span># These replace cron&#39;s entries</span></span>
<span class="line"><span>1       5       cron.daily      run-parts --report /etc/cron.daily</span></span>
<span class="line"><span>7       10      cron.weekly     run-parts --report /etc/cron.weekly</span></span>
<span class="line"><span>@monthly        15      cron.monthly    run-parts --report /etc/cron.monthly</span></span>
<span class="line"><span>@daily    10    example.daily   /bin/bash /home/aaronkilik/bin/backup.sh</span></span></code></pre></div><p>下面是 cron 以及 anacron 的比较，帮助你理解何时用他们其中一个。</p><div class="table-wrap"><table><thead><tr><th>cron</th><th>anacron</th></tr></thead><tbody><tr><td>它是守护进程</td><td>它不是守护进程</td></tr><tr><td>适合服务器</td><td>适合桌面/笔记本电脑</td></tr><tr><td>可以让你以分钟级运行计划任务</td><td>只能让你以天为基础来运行计划任务</td></tr><tr><td>关机时不会执行计划任务</td><td>如果计划任务到期，机器是关机的，那么它会在机器下次开机后执行计划任务</td></tr><tr><td>普通用户和 root 用户都可以使用</td><td>只有 root 用户可以使用（使用特定的配置启动普通任务）</td></tr></tbody></table></div><p>cron 和 anacron 主要的区别在于 cron 能在那些持续运行的机器上有效地运行，而 anacron 是针对那些会在一天内或者一周内会关机的机器。</p><p>如果你还知道其他方式，请在评论栏中与我们分享。</p><hr><p>作者简介：</p><p>Aaron Kili 是一个 Linux 和 F.O.S.S 爱好者、Linux 系统管理员、网络开发人员，现在也是 TecMint 的内容创作者，他喜欢和电脑一起工作，坚信共享知识。</p><hr>`,33)),o("p",null,[n[10]||(n[10]=a("via: ",-1)),t(s,{href:"https://www.tecmint.com/cron-vs-anacron-schedule-jobs-using-anacron-on-linux/"},{default:e(()=>[...n[9]||(n[9]=[a("https://www.tecmint.com/cron-vs-anacron-schedule-jobs-using-anacron-on-linux/",-1)])]),_:1})]),o("p",null,[n[14]||(n[14]=a("作者：",-1)),t(s,{href:"https://www.tecmint.com/author/aaronkili/"},{default:e(()=>[...n[11]||(n[11]=[a("Aaron Kili",-1)])]),_:1}),n[15]||(n[15]=a(" 译者：",-1)),t(s,{href:"https://github.com/geekpi"},{default:e(()=>[...n[12]||(n[12]=[a("geekpi",-1)])]),_:1}),n[16]||(n[16]=a(" 校对：",-1)),t(s,{href:"https://github.com/wxy"},{default:e(()=>[...n[13]||(n[13]=[a("wxy",-1)])]),_:1})]),o("p",null,[n[19]||(n[19]=a("本文由 ",-1)),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...n[17]||(n[17]=[a("LCTT",-1)])]),_:1}),n[20]||(n[20]=a(" 原创编译，",-1)),t(s,{href:"https://linux.cn/"},{default:e(()=>[...n[18]||(n[18]=[a("Linux中国",-1)])]),_:1}),n[21]||(n[21]=a(" 荣誉推出",-1))])])}const L=i(c,[["render",u]]);export{y as __pageData,L as default};
